class IperfProcessInteractiveShell(object):

    def __init__(self, ue_pc_ssh_client):
        self._ue_pc_ssh = ue_pc_ssh_client
        self._pid = None
        self._adb_pid = None
        self._cmd = None
        self._adb_cmd = None

    @property
    def pid(self):
        """ Get process id.

        :return:        Shell process id.
        :rtype:         string
        """
        return self._pid

    @pid.setter
    def pid(self, pid):
        """ Set process id.

        :param string pid:      Shell process id.
        """
        if self._pid is not None:
            raise ProcessIsAlreadyRunning("{} process is running".format(
                self.__class__.__name__))
        self._pid = pid

    @property
    def adb_pid(self):
        """ Get process id.

        :return:        Shell process id.
        :rtype:         string
        """
        return self._adb_pid

    @adb_pid.setter
    def adb_pid(self, adb_pid):
        """ Set process id.
        :param string pid:      Shell process id.
        """
        if self._adb_pid is not None:
            raise ProcessIsAlreadyRunning("{} process is running".format(
                self.__class__.__name__))
        self._adb_pid = adb_pid

    def start_process(self, cmd, log_file):
        self._ue_log = log_file
        logger.debug("UE log: {}".format(self._ue_log))
        self._execute('pwd')
        output = self._execute(cmd)
        logger.debug("Output after starting process: {}".format(output))
        # Find the last line that is a number (PID)
        pid = None
        for line in reversed(output):
            match = re.match(r'^\d+$', line.strip())
            if match:
                pid = int(line.strip())
                break
        if pid is None:
            logger.error("Could not extract PID from output: {}".format(output))
            raise StartProcessError("{} process was not started".format(cmd))
        self.adb_pid = pid
        logger.debug("Adb iperf process id : {}".format(self.adb_pid))
        self._is_process_started(self.adb_pid, cmd)

