    def get_log_file(self):
        dest = 'execution_logs/{}'.format(self._ue_log)
        logger.debug("Destination filename for ue log file: {}".format(dest))
        if not os.path.exists(os.path.dirname(dest)):
            os.makedirs(os.path.dirname(dest))
        # iperf_log_content = self._execute('cat {}'.format(self._ue_log))
        self._ue_pc_ssh.write('cat {} \n'.format(self._ue_log))
        time.sleep(1)
        iperf_log_content = self._ue_pc_ssh.read()
        logger.debug("iperf log content \n {}".format(iperf_log_content))
        with open(dest, 'w') as log_fh:
            log_fh.write(iperf_log_content)

        if self._ue_pc_ssh is None:
            move(self._ue_log, dest)
        else:
            # self._ue_pc_ssh.get_file(self._ue_log, 'execution_logs/')
            self._ue_pc_ssh.execute_command('rm -f ' + self._ue_log)
        return dest

    def execute(self, cmd):
        self._execute(cmd)

    def _execute(self, cmd):
        # if ssh is None:
        #     try:
        #         out = subprocess.check_output(cmd, shell=True)
        #         out = out.strip()
        #     except subprocess.CalledProcessError:
        #         raise IperfExecutionError()
        #     else:
        #         return out
        # else:
        logger.info('cmd: {}'.format(cmd))
        self._ue_pc_ssh.write(cmd + '\n')
        time.sleep(1)
        output = self._read_output()
        time.sleep(1)

        cmd = 'echo $?'
        self._ue_pc_ssh.write(cmd + '\n')
        time.sleep(1)
        exit_code = self._read_output()
        exit_code = int(self._fetch_exit_code(exit_code))
        logger.debug('output:\n {}\n\nexit code: {}'.format(output, exit_code))
        if int(exit_code) != 0:
            raise IperfExecutionError()
        return output

    def _fetch_exit_code(self, out_val):
        try:
            # data = pd.Series(out_val)
            # for data_val in data:
                # if not pd.to_numeric(data_val, errors='coerce'):
                #     return data_val
            for data_val in out_val:
        # Try to convert to int, skip if not possible
                try:
                    val = int(data_val)
                    return val
                except (ValueError, TypeError):
                    continue
        except Exception as e:
            Exception("Failed while fetching exit code :: {}".format(e))

    def _read_output(self):
        out = self._ue_pc_ssh.read()
        out = out.strip()
        out = decode_str(out)
        out = out.splitlines()
        logger.debug('raw output: {}'.format(out))
        # Only remove empty or prompt lines, not the actual PID
        out = [line for line in out if line and not line.startswith('$')]
        logger.debug('filtered output: {}'.format(out))
        return out

    def _is_process_stopped(self, pid):
        start = time.time()
        try:
            while time.time() - start < 10:
                self._pid_exists(pid)
        except IperfExecutionError:
            # self._pid = None
            sys.exc_clear()
        else:
            self._execute('kill -9 {}'.format(pid))
            # raise StopProcessError('"%s" process can not be
            # stopped on iperf machine' % cmd )

    def _is_process_started(self, pid, cmd):
        start = time.time()
        try:
            while time.time() - start < 10:
                self._pid_exists(pid)
        except IperfExecutionError:
            raise StartProcessError("{} process was not started".format(cmd))

    def _pid_exists(self, pid):
        self._execute('ps -p {}'.format(pid))
